<?php $active_module='ai'; require_once __DIR__ . '/layout.php'; require_once __DIR__ . '/../config/listing_integrity.php'; $u=$supplier_user; $q=db()->prepare("SELECT * FROM ai_insights WHERE supplier_id=? ORDER BY CASE priority WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, created_at DESC"); $q->execute([$u['supplier_id']]); $insights=$q->fetchAll(); $pq=db()->prepare('SELECT * FROM properties WHERE supplier_id=?'); $pq->execute([$u['supplier_id']]); $props=$pq->fetchAll(); $avgScore=0; $readyCount=0; if($props){ $total=0; foreach($props as $p){ $r=listing_readiness($p); $total+=$r['score']; if($r['ready'])$readyCount++; } $avgScore=(int)round($total/count($props)); } supply_start('NEXUS AI Merkezi', $active_module); ?>
